package org.hermesmobile.app

import kotlinx.serialization.json.*
import org.hermesmobile.app.data.*
import org.junit.Assert.*
import org.junit.Test

class CredentialPoolTest {
    private val owner=ManagementTarget("a".repeat(64),"https://hermes.example/prefix/","worker","password · fixture")
    private fun row(index:Int,id:String,source:String="env:PRIVATE_FIXTURE_KEY",count:Long=7,status:String="ok")=buildJsonObject {put("index",index);put("id",id);put("label","Fixture label");put("source",source);put("auth_type","api_key");put("priority",index-1);put("last_status",status);put("request_count",count);put("has_refresh",false);put("token_preview","private-token-preview-fixture")}
    private fun raw(entries:List<JsonObject> = listOf(row(1,"first"),row(2,"second")))=buildJsonObject {put("providers",buildJsonArray {add(buildJsonObject {put("provider","openrouter");put("entries",JsonArray(entries))})})}
    private fun inventory(j:JsonObject=raw())=CredentialPoolInventory.parse(j,owner,"b".repeat(64))
    private fun reply(provider:String="openrouter",count:Long=2)=buildJsonObject {put("ok",true);put("provider",provider);put("count",count)}
    @Test fun projectionDropsPreviewAndRawSourceFieldsAndIsImmutable() {val inv=inventory();assertFalse(inv.toString().contains("PRIVATE"));assertFalse(inv.providers.toString().contains("PRIVATE"));assertFalse(inv.providers.first().entries.toString().contains("private"));assertTrue(runCatching {(inv.providers as MutableList).clear()}.isFailure);assertTrue(runCatching {(inv.providers.first().entries as MutableList).clear()}.isFailure);assertEquals(PoolSourceKind.Environment,inv.providers.first().entries.first().sourceKind);val labeled=inventory(raw(listOf(JsonObject(row(1,"first")+mapOf("label" to JsonPrimitive("/private/label-fixture"))))));val entry=labeled.providers.first().entries.first();assertEquals("/private/label-fixture",entry.label);assertFalse(CredentialPoolRequest.remove(labeled,"openrouter",entry).summary().toString().contains("/private/label-fixture"))}
    @Test fun liveUsageAndStatusDoNotInvalidateStructuralReview() {val inv=inventory();assertTrue(inv.sameProvider(inventory(raw(listOf(row(1,"first",count=Long.MAX_VALUE,status="dead"),row(2,"second")))),"openrouter"));assertEquals(PoolReportedStatus.Ok,inv.providers.first().entries.first().status)}
    @Test fun orderIdentityLabelPriorityRefreshAndHiddenSourceChangesInvalidateReview() {
        val original=inventory();val first=row(1,"first");val second=row(2,"second")
        for(rows in listOf(listOf(row(1,"second"),row(2,"first")),listOf(row(1,"first",source="env:OTHER_PRIVATE_KEY"),second),listOf(JsonObject(first+mapOf("label" to JsonPrimitive("Other"))),second),listOf(JsonObject(first+mapOf("priority" to JsonPrimitive(99))),second),listOf(JsonObject(first+mapOf("has_refresh" to JsonPrimitive(true))),second))) assertFalse(original.sameProvider(inventory(raw(rows)),"openrouter"))
    }
    @Test fun malformedSelectorsDuplicatesAndUntypedFieldsCannotBecomeActionableRows() {
        for(rows in listOf(listOf(row(2,"first")),listOf(row(1,"same"),row(2,"same")),listOf(JsonObject(row(1,"first")+mapOf("has_refresh" to JsonPrimitive("false")))),listOf(JsonObject(row(1,"first")+mapOf("index" to JsonPrimitive("1")))),listOf(row(1,"first",count=-1)))) assertTrue(runCatching {inventory(raw(rows))}.exceptionOrNull() is CredentialPoolUnavailable)
        val group=raw().items("providers").single();assertTrue(runCatching {inventory(buildJsonObject {put("providers",JsonArray(listOf(group,group)))})}.isFailure)
    }
    @Test fun providerSelectorsSupportCanonicalCustomAndUnicodeWithoutPathAmbiguity() {for(id in listOf("openrouter","custom:my-endpoint","custom:测试","plugin.provider-v2")) assertTrue(id,CredentialPoolProtocol.provider(id));for(id in listOf("..",".","custom:","OpenRouter","pool/other","pool\\other","pool%2Fother","pool?key=x"," pool")) assertFalse(id,CredentialPoolProtocol.provider(id))}
    @Test fun freshAddHasExactSecretBodyAndPrivateReceiptSummary() {
        val request=CredentialPoolRequest.add(inventory(),"openrouter","  fresh-key-fixture  "," private-label-fixture ");val body=request.body();assertEquals(setOf("provider","api_key","label"),body.keys);assertEquals("fresh-key-fixture",body.text("api_key"));assertEquals("private-label-fixture",body.text("label"));assertFalse(request.summary().toString().contains("fresh-key-fixture"));assertFalse(request.summary().toString().contains("private-label-fixture"));assertFalse(request.toString().contains("fresh-key"));assertFalse(CredentialPoolRequest.add(inventory(),"openrouter","fresh-key-fixture").body().containsKey("label"))
    }
    @Test fun maskedOrControlCredentialsCannotBeSubmitted() {for(value in listOf("","   ","***","abcd...wxyz","key\nfixture")) assertTrue(runCatching {CredentialPoolRequest.add(inventory(),"openrouter",value)}.isFailure);assertTrue(runCatching {CredentialPoolRequest.add(inventory(),"openrouter","fresh-key-fixture","label\nfixture")}.isFailure)}
    @Test fun removalRequiresAnActualReviewedRowAndRecordsOnlyRequestedIdentity() {val inv=inventory();val row=inv.providers.first().entries[1];val request=CredentialPoolRequest.remove(inv,"openrouter",row);assertEquals(JsonPrimitive(2),request.summary()["requested_index"]);assertEquals("second",request.summary().text("reviewed_id"));assertFalse(request.summary().toString().contains("Fixture label"));assertTrue(runCatching {CredentialPoolRequest.remove(inv,"openrouter",inventory().providers.first().entries[1])}.isFailure)}
    @Test fun onlyExactTypedAcknowledgmentsSettleTheRequest() {val request=CredentialPoolRequest.add(inventory(),"openrouter","fresh-key-fixture");for(j in listOf(reply("other"),JsonObject(reply()+mapOf("ok" to JsonPrimitive("true"))),JsonObject(reply()-"count"),JsonObject(reply()+mapOf("count" to JsonPrimitive("2"))),reply(count=-1))) assertTrue(runCatching {request.acknowledge(j)}.isFailure)}
    @Test fun cleanupDetailsBecomeCountsWithoutPrivateTextAndNeverEraseKnownAck() {
        val inv=inventory();val request=CredentialPoolRequest.remove(inv,"openrouter",inv.providers.first().entries.last())
        val full=JsonObject(reply()+mapOf("cleaned" to buildJsonArray {add("private/path/fixture")},"hints" to buildJsonArray {add("private-cli-fixture");add("private-email@example.test")}));val summary=request.acknowledge(full);assertEquals(JsonPrimitive(1),summary["cleanup_message_count"]);assertEquals(JsonPrimitive(2),summary["hint_message_count"]);assertFalse(summary.toString().contains("private"))
        val malformed=request.acknowledge(JsonObject(reply()+mapOf("cleaned" to JsonPrimitive("private-error"))));assertEquals(JsonPrimitive(false),malformed["cleanup_report_available"]);assertEquals("second",malformed.text("reviewed_id"));assertFalse(malformed.containsKey("removed_id"))
    }
    @Test fun reportedCountsAreNotTreatedAsCausalIdentityOrHealthProof() {val request=CredentialPoolRequest.add(inventory(),"openrouter","fresh-key-fixture");assertEquals(JsonPrimitive(999),request.acknowledge(reply(count=999))["reported_count"]);assertEquals(PoolReportedStatus.Other,inventory(raw(listOf(row(1,"first",status="future-state")))).providers.first().entries.first().status)}
    @Test fun sourceClassificationKeepsCanonicalAndExternalOwnershipDistinct() {assertEquals(PoolSourceKind.HermesOAuth,CredentialPoolProtocol.sourceKind("openai-codex","manual:device_code"));assertEquals(PoolSourceKind.ProviderHook,CredentialPoolProtocol.sourceKind("nous","manual:device_code"));assertEquals(PoolSourceKind.ExternalCLI,CredentialPoolProtocol.sourceKind("anthropic","claude_code"));assertEquals(PoolSourceKind.Configuration,CredentialPoolProtocol.sourceKind("custom:fixture","config:/private/fixture"))}
    @Test fun privateCleanupReportIsBoundImmutableAndNeverRenderedByToString() {val response=JsonObject(reply()+mapOf("cleaned" to buildJsonArray {add("private/path")},"hints" to buildJsonArray {add("private-command")}));val report=PoolCleanupReport.parse(response,owner,"b".repeat(64),"receipt-fixture","openrouter")!!;assertEquals(owner,report.owner);assertEquals("receipt-fixture",report.receiptKey);assertEquals("private-command",report.hints.single());assertFalse(report.toString().contains("private"));assertTrue(runCatching {(report.hints as MutableList).clear()}.isFailure);assertNull(PoolCleanupReport.parse(JsonObject(response+mapOf("provider" to JsonPrimitive("other"))),owner,"b".repeat(64),"receipt-fixture","openrouter"))}
    @Test fun changedOwnerOrHomeCannotReuseStructuralReview() {val inv=inventory();assertFalse(inv.sameProvider(CredentialPoolInventory(owner.copy(actor="password · other"),inv.homeId,inv.providers),"openrouter"));assertFalse(inv.sameProvider(CredentialPoolInventory(owner,"c".repeat(64),inv.providers),"openrouter"))}
}
